<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Finance;
use HardnessMcp\Context\ExecutionContext;use HardnessMcp\Tools\Presentation\ToolResultPresenter;use HardnessMcp\Tools\ToolDefinition;use HardnessMcp\Tools\ToolExecutionResult;use HardnessMcp\Tools\ToolInterface;use InvalidArgumentException;
final class FinanceSummaryTool implements ToolInterface {private string $kind;private FinanceSummaryHandler $handler;private ToolResultPresenter $presenter;public function __construct(string $kind,FinanceSummaryHandler $handler,?ToolResultPresenter $presenter=null){$this->kind=$kind;$this->handler=$handler;$this->presenter=$presenter??new ToolResultPresenter();}public function getDefinition():ToolDefinition{return FinanceSummaryDefinition::forKind($this->kind);} /** @param array<string,mixed> $arguments */ public function execute(array $arguments,ExecutionContext $context):ToolExecutionResult{$prefix=$this->kind==='receivable'?'receivables':'payables';try{$result=$this->handler->handle(FinanceSummaryInput::fromArguments($arguments),$context);}catch(InvalidArgumentException $e){return $this->presenter->functionalError($prefix.'_summary_invalid_period',$e->getMessage(),'tools_call_'.$prefix.'_summary_invalid_period');}catch(\Throwable $e){return $this->presenter->functionalError($prefix.'_summary_unavailable','Não foi possível consultar o resumo financeiro agora. Tente novamente.','tools_call_'.$prefix.'_summary_unavailable');}if(($arguments['view']??'summary')==='titles')return $this->presenter->report($result,$this->kind==='receivable'?'Títulos a receber':'Títulos a pagar',[], 'rows', [['path'=>'partner_name','label'=>$this->kind==='receivable'?'Cliente':'Fornecedor'],['path'=>'invoice_number','label'=>'NF'],['path'=>'invoice_issued_date','label'=>'Emissão','format'=>'date'],['path'=>'document_number','label'=>'Documento'],['path'=>'due_date','label'=>'Vencimento','format'=>'date'],['path'=>'open_amount','label'=>'Saldo','format'=>'money'],['path'=>'carrier_name','label'=>'Portador'],['path'=>'origin','label'=>'Origem']]);return $this->presenter->report($result,$this->kind==='receivable'?'Resumo de contas a receber':'Resumo de contas a pagar',[['path'=>'summary.total_amount','label'=>'Total','format'=>'money'],['path'=>'summary.open_amount','label'=>'Em aberto','format'=>'money'],['path'=>'summary.overdue_amount','label'=>'Vencido','format'=>'money'],['path'=>'summary.title_count','label'=>'Títulos']],'rows',array_merge($this->rowKeys((string)$result['group_by']),[['path'=>'total_amount','label'=>'Total','format'=>'money'],['path'=>'open_amount','label'=>'Em aberto','format'=>'money'],['path'=>'overdue_amount','label'=>'Vencido','format'=>'money'],['path'=>'title_count','label'=>'Títulos']]));} /** @return array<int,array<string,mixed>> */ private function rowKeys(string $groupBy):array{$fields=['day'=>[['path'=>'date','label'=>'Vencimento','format'=>'date']],'month'=>[['path'=>'month','label'=>'Mês','format'=>'date']],'partner'=>[['path'=>'partner_id','label'=>$this->kind==='receivable'?'Cliente':'Fornecedor'],['path'=>'partner_name','label'=>'Nome']],'carrier'=>[['path'=>'carrier_id','label'=>'Portador'],['path'=>'carrier_name','label'=>'Nome']],'origin'=>[['path'=>'origin','label'=>'Origem']],'status'=>[['path'=>'status','label'=>'Situação']]];return $fields[$groupBy]??[];}}
